// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    TimelockController c;
    bytes4 ERC165_ID = type(IERC165Probe).interfaceId;
    bytes4 ACCESS_ID = type(IERC165Probe).interfaceId ^ bytes4(uint32(0x0000ff00));

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selectorSeed) public {
        bytes4 selector = bytes4(uint32(uint256(bound(selectorSeed, 0, type(uint32).max))));
        vm.assume(selector != bytes4(0));
        // Reference supports both the IAccessControl id and the IERC165 id (via super);
        // for any other id it must return false. In particular, IERC165's own id is
        // always supported by the reference (super.supportsInterface) but not by the mutant.
        bool expected = (selector == ERC165_ID);
        bool ok = c.supportsInterface(selector == ERC165_ID ? ERC165_ID : selector);
        // general rule: supportsInterface(x) iff x == ERC165_ID or x == IAccessControl id
        // Drive through public surface: check the ERC165 id behaviour directly.
        bool erc165Support;
        try c.supportsInterface(ERC165_ID) returns (bool r) {
            erc165Support = r;
        } catch {
            erc165Support = false;
        }
        assertTrue(erc165Support, "ERC165 interface id must be supported");
    }
}
